import sys

data = sys.stdin.read().split()
n = int(data[0])
m = int(data[1])
nxt = {}
prv = {}
parent = list(range(n + 1))

def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

ok = True
idx = 2
for _ in range(m):
    a = int(data[idx])
    b = int(data[idx + 1])
    idx += 2
    if nxt.get(a, b) != b or prv.get(b, a) != a:
        ok = False
        continue
    if a in nxt:
        continue
    nxt[a] = b
    prv[b] = a
    ra = find(a)
    rb = find(b)
    if ra == rb:
        ok = False
    else:
        parent[ra] = rb
if not ok:
    print(-1)
else:
    segs = []
    for v in range(1, n + 1):
        if v not in prv:
            seg = [v]
            while seg[-1] in nxt:
                seg.append(nxt[seg[-1]])
            segs.append(seg)
    segs.sort()
    print(" ".join(str(x) for s in segs for x in s))
